import collections,hashlib,inspect,json,math,random,string
from vs import corpus,ivtff,refcorpus
DIGITS='akr';LETTERS=string.ascii_lowercase;LIMIT=16

def payload(w):
 return ''.join(''.join(DIGITS[(ord(c)-97)//3**d%3] for d in (2,1,0)) for c in w)
def unpayload(s):
 if not s or len(s)%3 or any(c not in DIGITS for c in s):raise ValueError('bad digits')
 vals=[sum(DIGITS.index(s[i+j])*3**(2-j) for j in range(3)) for i in range(0,len(s),3)]
 if any(x>=26 for x in vals):raise ValueError('bad code')
 return ''.join(chr(97+x) for x in vals)
def encode(w,enc,variant):
 if not w or any(c not in LETTERS for c in w):raise ValueError('plaintext outside a-z')
 if variant!='escape_only' and w in enc:return enc[w]
 return ('q' if variant=='dictionary_only' or len(w)>LIMIT else 'y')+payload(w)
def decode(w,dec,variant):
 if not w:raise ValueError('empty cipher')
 if w[0] in ('q','y'):
  out=unpayload(w[1:])
  if w[0]=='y' and (variant=='dictionary_only' or len(out)>LIMIT):raise ValueError('bad bounded escape')
  if w[0]=='q' and variant!='dictionary_only' and len(out)<=LIMIT:raise ValueError('bad fallback')
  return out
 return dec[w]

def gamma(n):
 assert n>0
 b=bin(n)[2:];return '0'*(len(b)-1)+b
def ungamma(s,i):
 j=i
 while j<len(s) and s[j]=='0':j+=1
 if j==len(s):raise ValueError('truncated gamma')
 n=j-i+1;end=j+n
 if end>len(s):raise ValueError('truncated gamma')
 return int(s[j:end],2),end
def word(w):
 assert w and all(c in LETTERS for c in w)
 return gamma(len(w))+''.join(format(ord(c)-97,'05b') for c in w)
def unword(s,i):
 n,i=ungamma(s,i);end=i+5*n
 if end>len(s):raise ValueError('truncated word')
 bits=s[i:end];values=[int(bits[j:j+5],2) for j in range(0,len(bits),5)]
 if any(v>=26 for v in values):raise ValueError('unused alphabet code')
 return ''.join(chr(v+97) for v in values),end
def dictbits(enc):
 s=gamma(len(enc)+1)
 for k,v in sorted(enc.items()):s+=word(k)+word(v)
 return s
def undict(s):
 n,i=ungamma(s,0);out={}
 for _ in range(n-1):
  a,i=unword(s,i);b,i=unword(s,i);out[a]=b
 assert i==len(s);return out
def stream(ws):return gamma(len(ws)+1)+''.join(word(w) for w in ws)
def unstream(s):
 n,i=ungamma(s,0);out=[]
 for _ in range(n-1):w,i=unword(s,i);out.append(w)
 assert i==len(s);return out

codec_src="import string\nDIGITS='akr'; LETTERS=string.ascii_lowercase; LIMIT=16\n"+''.join(inspect.getsource(f) for f in (payload,unpayload,encode,decode,gamma,ungamma,word,unword,dictbits,undict,stream,unstream))
# Fixed header stores the exact codec source as gamma(byte count)+UTF-8 bits;
# interpreter and variant convention are shared across all compared schemes.
codec_bits=len(gamma(len(codec_src.encode())))+8*len(codec_src.encode())+2
BOOKS=('it_villani','fr_rose','en_chaucer');seeds=(19,37,73);train,_=corpus.split_pages('practice','zl')
codes=sorted(set(w for p in train for l in p.lines if l.unit=='P' for w in l.words if w and w.isascii() and w.islower() and w.isalpha() and not ivtff.uncertain(w) and w[0] not in 'qy'))
assert len(codes)>=1000
out={'config':{'books':BOOKS,'seeds':seeds,'code_candidates':len(codes),'marker_escape':'y','marker_fallback':'q','digits':DIGITS,'limit':LIMIT,'codec_source_bytes':len(codec_src.encode()),'codec_source_and_variant_bits':codec_bits,'plain_model':'P(w)=52^(-len(w)) for nonempty lowercase ASCII words'},'results':{}}
for book in BOOKS:
 e=next(x for x in refcorpus.pins() if x['id']==book);assert hashlib.sha256(open(e['file'],'rb').read()).hexdigest()==e['sha256'];words=' '.join(refcorpus.blocks_of(book)).split();assert len(words)>=75000 and all(w and all(c in LETTERS for c in w) for w in words[:75000]);freq=collections.Counter(words[:50000]);common=sorted(freq,key=lambda w:(-freq[w],w))[:1000];test=words[50000:75000];out['results'][book]={}
 for seed in seeds:
  pool=codes[:];random.Random(seed).shuffle(pool);enc=dict(zip(common,pool));dec={v:k for k,v in enc.items()};assert len(dec)==1000
  rr={}
  for variant in ('dictionary_only','escape_only','combined'):
   key={} if variant=='escape_only' else enc;rawkey=dictbits(key);assert undict(rawkey)==key
   cipher=[encode(w,key,variant) for w in test];wire=stream(cipher);returned=unstream(wire);inv={v:k for k,v in key.items()};assert [decode(w,inv,variant) for w in returned]==test
   rr[variant]={'tokens':len(test),'dictionary_tokens':sum(w in key for w in test),'bounded_escape_tokens':sum(w.startswith('y') for w in cipher),'fallback_tokens':sum(w.startswith('q') for w in cipher),'cipher_chars':sum(map(len,cipher)),'cipher_stream_bits':len(wire),'dictionary_bits':len(rawkey),'codec_bits':codec_bits,'explicit_components_total_bits':len(wire)+len(rawkey)+codec_bits,'plaintext_model_bits':sum(len(w) for w in test)*math.log2(52),'preimage_bits_given_key_and_cipher':0,'exact_roundtrip':True}
  out['results'][book][str(seed)]=rr
print(json.dumps(out,indent=2))
